body{
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  background:
    radial-gradient(1200px 600px at 15% 10%, rgba(110,168,254,0.25), transparent 60%),
    radial-gradient(900px 500px at 90% 20%, rgba(74,222,128,0.18), transparent 60%),
    var(--bg);
  color: var(--text);
}

.app{
  max-width: 820px;
  margin: 40px auto;
  padding: 0 16px 40px;
}

.header{
  margin-bottom: 16px;
}
.header h1{
  margin: 0 0 6px;
  font-size: 34px;
  letter-spacing: -0.02em;
}
.subtitle{
  margin: 0;
  color: var(--muted);
}

.card{
  background: var(--card);
  border: 1px solid var(--card-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px;
  margin: 14px 0;
}

.card-header{
  display:flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
}
.card-header h2{
  margin: 0;
  font-size: 18px;
}
.count{
  color: var(--muted);
  font-weight: 600;
}

.todo-form .label{
  display:block;
  margin-bottom: 8px;
  color: var(--muted);
  font-weight: 600;
  font-size: 13px;
}

.input-row{
  display:flex;
  gap: 10px;
}
input[type="text"]{
  flex: 1;
  padding: 12px 12px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,0.16);
  background: rgba(0,0,0,0.25);
  color: var(--text);
  outline: none;
}
input[type="text"]::placeholder{
  color: rgba(255,255,255,0.45);
}
input[type="text"]:focus{
  border-color: rgba(110,168,254,0.65);
  box-shadow: 0 0 0 4px rgba(110,168,254,0.15);
}

.btn{
  border: 0;
  border-radius: 12px;
  padding: 12px 14px;
  font-weight: 700;
  cursor: pointer;
  color: #08101f;
  background: rgba(255,255,255,0.7);
  transition: transform 0.05s ease, opacity 0.15s ease;
}
.btn:hover{ opacity: 0.95; }
.btn:active{ transform: translateY(1px); }

.btn.primary{
  background: linear-gradient(180deg, rgba(110,168,254,1), rgba(110,168,254,0.75));
}
.btn.danger{
  background: linear-gradient(180deg, rgba(255,107,107,1), rgba(255,107,107,0.72));
  color: #1b0b0b;
}
.btn.ghost{
  background: rgba(255,255,255,0.08);
  color: var(--text);
  border: 1px solid rgba(255,255,255,0.14);
}

.hint{
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.todo-list{
  list-style: none;
  padding: 0;
  margin: 0;
  display:flex;
  flex-direction: column;
  gap: 10px;
}

.todo-item{
  display:flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px;
  border-radius: 14px;
  background: rgba(0,0,0,0.15);
  border: 1px solid rgba(255,255,255,0.10);
}
.todo-item-left{
  display:flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.todo-title{
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.todo-meta{
  color: var(--muted);
  font-size: 12px;
}

.todo-actions{
  display:flex;
  gap: 8px;
  flex-shrink: 0;
}

.todo-actions .btn{
  padding: 10px 12px;
  border-radius: 12px;
  font-size: 13px;
}

.empty{
  color: var(--muted);
  text-align: center;
  padding: 18px 8px 6px;
}

.form-editing .btn.primary{
  background: linear-gradient(180deg, rgba(74,222,128,1), rgba(74,222,128,0.75));
}
