## Step 2: Implement localStorage + render + CRUD (add/edit/delete)

Replace the contents of **`app.js`** with this:

```js
// todo-localstorage/app.js

const STORAGE_KEY = "todos:v1";

const $ = (sel) => document.querySelector(sel);

const todoForm = $("#todoForm");
const newTodoInput = $("#newTodo");
const todoList = $("#todoList");
const emptyState = $("#emptyState");
const countEl = $("#count");

// App state
let todos = [];
let editingId = null;

// Utilities
function loadTodos() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function saveTodos() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
}

function uid() {
  // Simple unique id good enough for a demo
  return `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function setEmptyStateVisibility() {
  const isEmpty = todos.length === 0;
  emptyState.style.display = isEmpty ? "block" : "none";
  countEl.textContent = String(todos.length);
}

// Rendering
function render() {
  // Clear list
  todoList.innerHTML = "";

  // Update count/empty
  setEmptyStateVisibility();

  if (todos.length === 0) return;

  for (const todo of todos) {
    const li = document.createElement("li");
    li.className = "todo-item";
    li.dataset.id = todo.id;

    li.innerHTML = `
      <div class="todo-item-left">
        <div class="todo-title" title="${escapeHtml(todo.text)}">${escapeHtml(todo.text)}</div>
        <div class="todo-meta">${escapeHtml(formatMeta(todo))}</div>
      </div>

      <div class="todo-actions">
        <button class="btn ghost btn-edit" type="button">Edit</button>
        <button class="btn danger btn-delete" type="button">Delete</button>
      </div>
    `;

    // Edit
    li.querySelector(".btn-edit").addEventListener("click", () => startEditing(todo.id));
    // Delete
    li.querySelector(".btn-delete").addEventListener("click", () => deleteTodo(todo.id));

    todoList.appendChild(li);
  }
}

// Helpers for safe HTML
function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function formatMeta(todo) {
  // Display created or updated time (local)
  const dt = new Date(todo.updatedAt ?? todo.createdAt);
  const time = dt.toLocaleString([], { year: "numeric", month: "short", day: "2-digit", hour: "2-digit", minute: "2-digit" });
  return todo.updatedAt ? `Updated: ${time}` : `Created: ${time}`;
}

// CRUD
function addTodo(text) {
  const now = Date.now();
  const todo = {
    id: uid(),
    text: text.trim(),
    createdAt: now,
    updatedAt: null,
  };
  todos.unshift(todo);
  saveTodos();
  render();
}

function startEditing(id) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) return;

  editingId = id;

  newTodoInput.value = todo.text;
  newTodoInput.focus();

  // Update button label
  const submitBtn = todoForm.querySelector('button[type="submit"]');
  submitBtn.textContent = "Save";

  // Optional: highlight state
  todoForm.classList.add("editing");
}

function cancelEditing() {
  editingId = null;
  newTodoInput.value = "";

  const submitBtn = todoForm.querySelector('button[type="submit"]');
  submitBtn.textContent = "Add";

  todoForm.classList.remove("editing");
}

function updateTodo(id, newText) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) return;

  todo.text = newText.trim();
  todo.updatedAt = Date.now();

  saveTodos();
  render();
}

function deleteTodo(id) {
  todos = todos.filter((t) => t.id !== id);

  // If deleting the one we're editing, cancel
  if (editingId === id) cancelEditing();

  saveTodos();
  render();
}

// Events
todoForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const text = newTodoInput.value.trim();
  if (!text) return;

  if (editingId) {
    updateTodo(editingId, text);
    cancelEditing();
  } else {
    addTodo(text);
    newTodoInput.value = "";
    newTodoInput.focus();
  }
});

// UX: Escape cancels edit
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && editingId) {
    cancelEditing();
  }
});

// Init
todos = loadTodos();
render();
```

