  document.getElementById("uploadBtn").addEventListener("click", async () => {
    const fileInput = document.getElementById("pdf");
    const status = document.getElementById("uploadStatus");
    const btn = document.getElementById("uploadBtn");

    if (!fileInput.files || fileInput.files.length === 0) {
      status.textContent = "Please choose a PDF file first.";
      return;
    }

    const file = fileInput.files[0];
    const form = new FormData();
    form.append("file", file);

    btn.disabled = true;
    status.textContent = "Uploading + indexing...";

    try {
      log("Uploading...");
      const data = await api("/upload", { method: "POST", body: form });
      log(data);
      status.textContent = "Indexed successfully (check Debug).";
    } catch (e) {
      status.textContent = "Error: " + e.message;
      log(e.message);
    } finally {
      btn.disabled = false;
    }
  });

  document.getElementById("chatBtn").addEventListener("click", async () => {
    const question = document.getElementById("question").value.trim();
    const topK = Number(document.getElementById("topK").value || 4);

    const status = document.getElementById("chatStatus");
    const btn = document.getElementById("chatBtn");

    if (!question) {
      status.textContent = "Please enter a question.";
      return;
    }

    btn.disabled = true;
    status.textContent = "Retrieving + generating answer...";

    try {
      const payload = { question, top_k: topK };
      log({ payload, note: "Calling /chat" });

      const data = await api("/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      document.getElementById("result").style.display = "block";
      document.getElementById("answer").textContent = data.answer || "";

      const sourcesEl = document.getElementById("sources");
      sourcesEl.innerHTML = "";

      (data.sources || []).forEach((s, i) => {
        const div = document.createElement("div");
        div.className = "source";
        div.innerHTML = `
          <div><b>Source ${i+1}</b> — ${escapeHtml(s.source || "unknown")} (chunk ${s.chunk_index ?? "?"})</div>
          <div class="muted" style="margin-top:6px;">
            ${escapeHtml(s.excerpt || "")}
          </div>
        `;
        sourcesEl.appendChild(div);
      });

      status.textContent = "Done.";
      log(data);
    } catch (e) {
      status.textContent = "Error: " + e.message;
      log(e.message);
    } finally {
      btn.disabled = false;
    }
  });

  function escapeHtml(str) {
    return String(str)
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }
</script>
</body>
</html>
