import { useMemo, useState } from "react";
import "./styles.css";

function formatLocalTime(dateStr) {
  // Open-Meteo returns local time in ISO-like string (e.g., "2026-06-08T14:00")
  // Create a Date for display; fall back to original string if parsing fails.
  const d = new Date(dateStr);
  if (Number.isNaN(d.getTime())) return dateStr;
  return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function conditionFromWeatherCode(code) {
  // Simple mapping (not exhaustive). Open-Meteo codes are WMO codes.
  const map = {
    0: "Clear sky",
    1: "Mainly clear",
    2: "Partly cloudy",
    3: "Overcast",
    45: "Fog",
    48: "Depositing rime fog",
    51: "Light drizzle",
    53: "Moderate drizzle",
    55: "Dense drizzle",
    56: "Light freezing drizzle",
    57: "Dense freezing drizzle",
    61: "Slight rain",
    63: "Moderate rain",
    65: "Heavy rain",
    66: "Light freezing rain",
    67: "Heavy freezing rain",
    71: "Slight snow fall",
    73: "Moderate snow fall",
    75: "Heavy snow fall",
    77: "Snow grains",
    80: "Slight rain showers",
    81: "Moderate rain showers",
    82: "Violent rain showers",
    85: "Slight snow showers",
    86: "Heavy snow showers",
    95: "Thunderstorm",
    96: "Thunderstorm with slight hail",
    99: "Thunderstorm with heavy hail",
  };
  return map[code] ?? `Weather code ${code}`;
}

async function geocodeCity(city) {
  // Open-Meteo geocoding endpoint
  // Docs: https://open-meteo.com/en/docs/geocoding-api
  const url = new URL("https://geocoding-api.open-meteo.com/v1/search");
  url.searchParams.set("name", city);
  url.searchParams.set("count", "5");
  url.searchParams.set("language", "en");
  url.searchParams.set("format", "json");

  const res = await fetch(url);
  if (!res.ok) throw new Error(`Geocoding failed (${res.status})`);
  const data = await res.json();

  if (!data?.results?.length) {
    throw new Error("No matching city found. Try another name.");
  }

  // Pick the most relevant (first) result
  const best = data.results[0];
  return {
    name: best.name,
    admin1: best.admin1,
    country: best.country,
    latitude: best.latitude,
    longitude: best.longitude,
    timezone: best.timezone,
  };
}

async function fetchForecast(lat, lon) {
  // Open-Meteo forecast endpoint
  // Docs: https://open-meteo.com/en/docs
  // We’ll request:
  // - current weather (with current units)
  // - hourly: temperature, weather code, precipitation, wind
  // - also timezone parameters so we get local times
  const url = new URL("https://api.open-meteo.com/v1/forecast");
  url.searchParams.set("latitude", lat);
  url.searchParams.set("longitude", lon);

  url.searchParams.set("current", "temperature_2m,weather_code,relative_humidity_2m,apparent_temperature,wind_speed_10m");
  url.searchParams.set("hourly", "temperature_2m,weather_code,precipitation_probability,precipitation,wind_speed_10m");
  url.searchParams.set("forecast_days", "2");
  url.searchParams.set("timezone", "auto");
  url.searchParams.set("models", "best_match");

  const res = await fetch(url);
  if (!res.ok) throw new Error(`Weather request failed (${res.status})`);
  const data = await res.json();

  const current = data.current;
  const hourly = data.hourly;

  if (!current || !hourly) {
    throw new Error("Unexpected weather data format.");
  }

  // Take next 12 hours from hourly.time starting "now"
  const times = hourly.time || [];
  const temp = hourly.temperature_2m || [];
  const codes = hourly.weather_code || [];
  const pop = hourly.precipitation_probability || [];
  const precip = hourly.precipitation || [];
  const wind = hourly.wind_speed_10m || [];

  // "next 12 hours" typically means 12 consecutive hourly entries including current hour.
  // We'll take 12 entries starting at index 0 because open-meteo hourly usually starts at now.
  const next12Count = 12;

  const forecast12 = times.slice(0, next12Count).map((t, i) => ({
    time: t,
    temperature: temp[i],
    weatherCode: codes[i],
    precipitationProbability: pop[i],
    precipitation: precip[i],
    windSpeed: wind[i],
  }));

  return { current, forecast12 };
}

export default function App() {
  const [city, setCity] = useState("");
  const [status, setStatus] = useState("idle"); // idle | loading | success | error
  const [error, setError] = useState("");
  const [result, setResult] = useState(null);

  const canSubmit = useMemo(() => city.trim().length > 0 && status !== "loading", [city, status]);

  async function onSubmit(e) {
    e.preventDefault();
    setError("");
    setStatus("loading");
    setResult(null);

    try {
      const trimmed = city.trim();
      const geo = await geocodeCity(trimmed);
      const weather = await fetchForecast(geo.latitude, geo.longitude);

      setResult({
        locationLabel: `${geo.name}${geo.admin1 ? `, ${geo.admin1}` : ""}, ${geo.country}`,
        timezone: geo.timezone,
        ...weather,
      });
      setStatus("success");
    } catch (err) {
      setError(err?.message ?? "Something went wrong.");
      setStatus("error");
    }
  }

  return (
    <div className="page">
      <header className="header">
        <h1>Weather Dashboard</h1>
        <p className="subtitle">City → current conditions + next 12 hours (Open-Meteo)</p>
      </header>

      <section className="card">
        <form onSubmit={onSubmit} className="searchRow">
          <input
            value={city}
            onChange={(e) => setCity(e.target.value)}
            placeholder="Enter a city (e.g., London)"
            aria-label="City name"
            className="searchInput"
          />
          <button disabled={!canSubmit} className="searchButton">
            {status === "loading" ? "Loading…" : "Search"}
          </button>
        </form>

        {status === "loading" && (
          <div className="state">
            <div className="spinner" aria-hidden="true" />
            <div>Fetching weather…</div>
          </div>
        )}

        {status === "error" && (
          <div className="state stateError">
            <div className="errorText">{error}</div>
          </div>
        )}

        {status === "success" && result && (
          <div className="content">
            <div className="location">
              <h2>{result.locationLabel}</h2>
              <div className="muted">Timezone: {result.timezone ?? "auto"}</div>
            </div>

            <div className="grid">
              <div className="panel">
                <h3>Current</h3>
                <div className="bigTemp">
                  {typeof result.current.temperature_2m === "number"
                    ? `${Math.round(result.current.temperature_2m)}°C`
                    : "—"}
                </div>
                <div className="cond">
                  {conditionFromWeatherCode(result.current.weather_code)}
                </div>

                <ul className="metaList">
                  <li>
                    Humidity:{" "}
                    <strong>{result.current.relative_humidity_2m ?? "—"}%</strong>
                  </li>
                  <li>
                    Feels like:{" "}
                    <strong>
                      {typeof result.current.apparent_temperature === "number"
                        ? `${Math.round(result.current.apparent_temperature)}°C`
                        : "—"}
                    </strong>
                  </li>
                  <li>
                    Wind:{" "}
                    <strong>{result.current.wind_speed_10m ?? "—"} km/h</strong>
                  </li>
                </ul>
              </div>

              <div className="panel forecastPanel">
                <h3>Next 12 hours</h3>
                <div className="forecastGrid">
                  {result.forecast12.map((h) => (
                    <div key={h.time} className="forecastCard">
                      <div className="forecastTime">{formatLocalTime(h.time)}</div>
                      <div className="forecastTemp">
                        {typeof h.temperature === "number" ? `${Math.round(h.temperature)}°` : "—"}
                      </div>
                      <div className="forecastCond">
                        {conditionFromWeatherCode(h.weatherCode)}
                      </div>
                      <div className="forecastSmall">
                        POP: {typeof h.precipitationProbability === "number" ? `${h.precipitationProbability}%` : "—"}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="hint muted">
              Tip: Try “San Francisco”, “Tokyo”, or “Berlin”.
            </div>
